// describeResource implements lld/07 §2's describe_resource: the live
// object as JSON (via the dynamic client, so one code path covers all eight
// supported Kinds) plus its own recently-involved Events inlined, exactly
// mirroring lld/07's stated shape ("Resource + inlined recent events for
// that object"). A failure fetching the supplementary events never fails
// the whole call once the object itself was fetched successfully — it's
// logged and the result carries an empty Events list instead.
func (e *ToolExecutor) describeResource(ctx context.Context, rawArgs json.RawMessage) (json.RawMessage, bool, error) {
	var args describeResourceArgs
	if err := json.Unmarshal(rawArgs, &args); err != nil {
		return nil, false, fmt.Errorf("invalid args: %w", err)
	}
	if args.Name == "" {
		return nil, false, errors.New("name is required")
	}
	gvk, err := parseGVKString(args.GVK)
	if err != nil {
		return nil, false, err
	}
	// resolveDescribableResource looks past supportedGVKs into the same
	// RBAC-intersected discovered watch set generic_predicates.go's
	// kind-agnostic detection already uses, when the gvk isn't one of the
	// ~30 kinds this file's authors have actually reviewed (BACKLOG.md E13).
	// reviewed says which redaction posture applies to the object below.
	res, reviewed, err := e.resolveDescribableResource(ctx, gvk)
	if err != nil {
		return nil, false, err
	}
	// Checked AFTER the kind lookup, because whether a namespace is required
	// depends on the kind: demanding one unconditionally made every
	// cluster-scoped kind (Node, PersistentVolume, StorageClass)
	// uncallable — caught by a live describe of a real Node, which failed
	// with "namespace is required" even though the resource lookup itself
	// had already been made namespace-aware.
	if err := requireNamespaceFor(res, args.Namespace); err != nil {
		return nil, false, err
	}

	obj, err := e.resourceInterface(res, args.Namespace).Get(ctx, args.Name, metav1.GetOptions{})
	if apierrors.IsNotFound(err) {
		return nil, false, notFoundError(gvk.Kind, args.Namespace, args.Name)
	}
	if err != nil {
		return nil, false, sanitizeK8sErr(err)
	}
	// Secret is the one kind in supportedGVKs whose live object must NEVER
	// be handed to mustMarshal(obj.Object) whole — see supportedGVKs' own
	// comment on this entry and secretMetadataOnly's doc comment below.
	// Checked on the parsed gvk (from the caller's own request), not on the
	// object's runtime type, but they agree here: supportedGVKs already
	// guarantees res.gvr resolves to exactly one kind, so there is no way to
	// reach this branch for anything other than a real Secret.
	// One time.Now() snapshot for the whole call, so every field this
	// describe_resource annotates — the relative-timestamp siblings below and
	// GitOpsHeadline's own recency reading — agrees on what "now" meant.
	now := time.Now()

	var objJSON json.RawMessage
	switch {
	case gvk == secretGVK:
		objJSON = mustMarshal(secretMetadataOnly(obj))
	case reviewed:
		// Every RFC3339 timestamp this object carries that relativeTimeFieldPolicy
		// (relative_time.go) recognizes gets an already-computed, signed
		// secondsUntil/secondsSince sibling — see that file's doc comment for why
		// (BUGS.md 105 / BACKLOG.md C9): the model must never be left to do its
		// own "is this in the future or the past" arithmetic on two raw
		// timestamp strings.
		objJSON = mustMarshal(annotateRelativeTimestamps(now.UTC(), obj.Object))
	default:
		// BACKLOG.md E13: gvk resolved only through discovery, so nobody has
		// reviewed this kind's schema for what it might hold — an arbitrary
		// CRD's spec/status/annotations are as good a place for a credential
		// as a Secret's data. redact.Object's structural rules are keyed on
		// field NAMES reviewed against supportedGVKs' ~30 kinds and were
		// never meant to be the only control for a schema they were never
		// written against; redact.AggressiveObject is. This runs INSIDE
		// describe_resource, in ADDITION to (never instead of) Execute's own
		// outer redact.Object wrap that still runs on everything this
		// function returns — see redact.AggressiveObject's own doc comment.
		objJSON = redact.AggressiveObject(mustMarshal(obj.Object))
	}

	var events []eventResult
	eventsRaw, _, err := e.getEvents(ctx, mustMarshal(getEventsArgs{
		Namespace:          args.Namespace,
		InvolvedObjectKind: gvk.Kind,
		InvolvedObjectName: args.Name,
	}))
	if err != nil {
		logger.WarnContext(ctx, "describe_resource: fetching events failed", slog.String("gvk", args.GVK), slog.String("namespace", args.Namespace), slog.String("name", args.Name), logging.Err(err))
	} else if err := json.Unmarshal(eventsRaw, &events); err != nil {
		logger.WarnContext(ctx, "describe_resource: decode events failed", logging.Err(err))
	}

	var gitOpsHeadline *gitopsinsight.Headline
	if gitopsinsight.DetectTool(obj) != "" {
		h := gitopsinsight.HeadlineFor(obj, gitopsinsight.Summarize(obj), now)
		if h.Text != "" {
			gitOpsHeadline = &h
		}
	}

	return mustMarshal(describeResourceResult{Object: objJSON, Events: events, GitOpsHeadline: gitOpsHeadline, Facts: stateFacts(obj, now)}), false, nil
}

// secretMetadataOnly turns a fetched Secret into the ONLY representation
// describe_resource is allowed to hand back for this kind: apiVersion, kind,
// a metadata block (name/namespace/labels/annotations/creationTimestamp —
// the same identity fields every other supportedGVKs kind returns), and
// type. Never data, never stringData.
//
// This builds a brand-new map field by field rather than copying obj.Object
// and deleting keys from it. That is a deliberate, load-bearing choice, not
// a style preference: a delete-based approach is only as safe as the list of
// keys it remembers to delete, and a future refactor of this function (or of
// the unstructured object's shape, if the Secret API ever grows a new
// top-level field) could silently start passing something through again. A
// function that only ever COPIES IN the handful of fields it names cannot
// leak a field nobody named, because there is no path through it that
// forwards anything by default. TestDescribeResource_SecretReturnsMetadataAndTypeOnly
// and TestListResources_SecretCannotBeEnumerated pin this from the outside.
//
// This is intentionally NOT routed through redact.Object's existing
// data/stringData handling — that package marks values Marker while keeping
// the keys (by design: "the config map has no database.url key at all" and
// "it has one whose contents we won't show you" are different diagnoses, see
// redact.go's own doc comment), which is exactly the "present but redacted"
// shape this task's brief says is not good enough for a Secret. The two
// fields this function keeps (metadata, type) hold no secret material to
// begin with, so there is nothing for redact.Object to do here — it still
// runs (Execute wraps every tool's output unconditionally), it just has
// nothing left to act on.
func secretMetadataOnly(obj *unstructured.Unstructured) map[string]any {
	metadata := map[string]any{
		"name":              obj.GetName(),
		"namespace":         obj.GetNamespace(),
		"creationTimestamp": obj.GetCreationTimestamp().UTC().Format(time.RFC3339),
	}
	if labels := obj.GetLabels(); len(labels) > 0 {
		metadata["labels"] = labels
	}
	if annotations := obj.GetAnnotations(); len(annotations) > 0 {
		metadata["annotations"] = annotations
	}
	out := map[string]any{
		"apiVersion": obj.GetAPIVersion(),
		"kind":       obj.GetKind(),
		"metadata":   metadata,
	}
	// type is a plain string field directly on Secret (not nested under
	// spec/status), read with the same NestedString accessor every other
	// field-specific read in this file uses — never obj.Object["type"]
	// directly, so a differently-shaped value (or its absence) degrades to
	// "no type reported" instead of a type assertion panic.
	if t, found, _ := unstructured.NestedString(obj.Object, "type"); found {
		out["type"] = t
	}
	return out
}
